"""specs_s200054.py - Sonnet-w2 factory + tail rows (generated by mkfamFT.py): the factory slot 0x44 stub (this passed as the stack arg) returns a random heap object or 0; INIT and the member callees record the SEH chain and the object's vtable word; fs:[0] compared; the heap object is compared after all stores."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(callees):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        p = r.choice([0, rnd(c, 0x600), rnd(c, 0x600), rnd(c, 0x600)])
        for a in callees:
            hook_rec(c, a, 0, ret=r.getrandbits(32), this=True, side=_side(c, p))
        eng = rnd(c, 0x1b00)
        c.emu.w32(0x70039c, eng)
        t = rnd(c, 0x40)
        mgr = obj(c, 0x40, {0x44: pystub(c, 1, ret=p, this=True, side=seh_record(c, 2))}, nslots=0x18)
        c.emu.w32(t + 8, mgr)
        c.emu.w32(eng + 0x9b, t)
        return [rnd(c, 0x10)]
    return gen


S(0x5659b0, 'GUESS famFT 0x5659b0', 'thiscall', None, ret='eax', gen=_mk([0x564460]), note='batch200054')
